+const animationPercentage: Ref<number> = ref(0)
+const animationVisible: Ref<boolean> = ref(false)
+
+// GSAP timeline for the icon above the section title
+let timeline: gsap.core.Timeline | null
+
+onMounted(() => {
+  startAnimation()
+})
